// Independent translation of the pinned prefix helper and explicit strict ABI.
fn main(...environment: Any) -> Any {
    assert environment is (Any, Any);
    assert environment.rest is (Any, Any);
    assert environment.rest.rest is nil;
    prefix(environment.first, environment.rest.first)
}

fn prefix(list: Any, tail: Any) -> Any {
    if list is nil {
        tail
    } else {
        assert list is (Any, Any);
        (list.first, prefix(list.rest, tail))
    }
}

puzzles.source:
use chialisp_oxide::OwnedTree;

/// Copy a proper list spine onto any tail tree, preserving every atom byte.
#[chialisp_oxide::puzzle]
pub fn puzzle<'a>(list: OwnedTree<'a>, tail: OwnedTree<'a>) -> OwnedTree<'a> {
    prefix(list, tail)
}

fn prefix<'a>(list: OwnedTree<'a>, tail: OwnedTree<'a>) -> OwnedTree<'a> {
    match list {
        OwnedTree::Atom([]) => tail,
        OwnedTree::Pair(first, rest) => OwnedTree::Pair(first, Box::new(prefix(*rest, tail))),
        OwnedTree::Atom(_) => panic!(),
    }
}

