rue.source:
fn main(...environment: Any) -> Bool {
    assert environment is (Any, Any);
    assert environment.rest is (Any, Any);
    assert environment.rest.rest is nil;
    let left = environment.first;
    let right = environment.rest.first;
    assert left is Bytes;
    assert right is Bytes;
    left != right
}

puzzles.source:
#[chialisp_oxide::puzzle]
pub fn puzzle(left: &[u8], right: &[u8]) -> bool {
    left != right
}

